// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();

// --- Data ---
const GRID_ROWS = [
  "MICHAELBXZQ",
  "TKEVINPAMWR",
  "OXCREEDYLTD",
  "BZANDYGTPFW",
  "YUWQJIMHKSI",
  "PARTYSURVIG",
  "VMXZBVNPONH",
  "STATIONERYT",
  "COFFEEMUGSM",
  "QWERTYPAPER",
];

type WordTarget = {
  word: string;
  start: [number, number]; // [row, col]
  end: [number, number];
  colIndex: number; // 0 for left column, 1 for right column in tracklist
};

// Ordered by animation sequence
const WORDS_TO_FIND: WordTarget[] = [
  { word: "Michael", start: [0, 0], end: [0, 6], colIndex: 0 },
  { word: "Dwight", start: [2, 10], end: [7, 10], colIndex: 0 },
  { word: "Pam", start: [1, 6], end: [1, 8], colIndex: 0 },
  { word: "Jim", start: [4, 4], end: [4, 6], colIndex: 0 },
  { word: "Andy", start: [3, 2], end: [3, 5], colIndex: 1 },
  { word: "Kevin", start: [1, 1], end: [1, 5], colIndex: 1 },
  { word: "Creed", start: [2, 2], end: [2, 6], colIndex: 1 },
  { word: "Toby", start: [1, 0], end: [4, 0], colIndex: 1 },
];



export type WordSearchAnimationProps = Record<string, any>;

const WordSearchAnimation: React.FC<WordSearchAnimationProps> = ({
  backgroundColor = "#FAF4ED",
  textColor = "#1E1E1E",
  highlightColor = "#D82A90",
  transparentBackground = false,
  durationInSeconds = 15,
  titleText = "DUNDER MIFFLIN EMPLOYEES",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timing ---
  const totalFrames = durationInSeconds * fps;
  const startDelay = fps * 1;
  const endDelay = fps * 2;
  const animatableFrames = totalFrames - startDelay - endDelay;
  const framesPerWord = animatableFrames / WORDS_TO_FIND.length;

  // --- Layout Calculations ---
  // Responsive units based on canvas width (assuming vertical 9:16 layout)
  const u = width / 100;
  const cols = 11;
  const rows = 10;
  
  // Grid container takes up 85% of width
  const gridContainerWidth = width * 0.85;
  const cellWidth = gridContainerWidth / cols;
  const cellHeight = cellWidth; // Square cells
  const gridContainerHeight = cellHeight * rows;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        paddingTop: height * 0.08,
      }}
    >
      {/* --- HEADER --- */}
      <div
        style={{
          width: "85%",
          borderBottom: `2px solid ${textColor}`,
          paddingBottom: 4 * u,
          marginBottom: 6 * u,
        }}
      >
        <h1
          style={{
            fontSize: 7 * u,
            fontWeight: 900,
            letterSpacing: "-0.02em",
            margin: 0,
            lineHeight: 1.1,
          }}
        >
          {titleText}
        </h1>
      </div>

      {/* --- TRACKLIST --- */}
      <div
        style={{
          width: "85%",
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          marginBottom: 8 * u,
        }}
      >
        {[0, 1].map((colIndex) => (
          <div key={`col-${colIndex}`} style={{ width: "45%", display: "flex", flexDirection: "column", gap: 1.5 * u }}>
            {WORDS_TO_FIND.map((item, index) => {
              if (item.colIndex !== colIndex) return null;

              // Calculate animation progress for this specific word's strikethrough
              const wordStartTime = startDelay + index * framesPerWord;
              // Strikethrough happens in the second half of the word's allocated time
              const strikeStart = wordStartTime + framesPerWord * 0.5;
              const strikeEnd = strikeStart + framesPerWord * 0.4;
              
              const strikeProgress = interpolate(
                frame,
                [strikeStart, strikeEnd],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              return (
                <div
                  key={item.word}
                  style={{
                    position: "relative",
                    fontSize: 4 * u,
                    fontWeight: 500,
                    alignSelf: "flex-start",
                  }}
                >
                  {item.word}
                  {/* Strikethrough Line */}
                  <div
                    style={{
                      position: "absolute",
                      top: "50%",
                      left: "-5%",
                      width: "110%",
                      height: Math.max(2, 0.4 * u),
                      backgroundColor: highlightColor,
                      transform: `scaleX(${strikeProgress}) rotate(-1deg)`,
                      transformOrigin: "left center",
                      borderRadius: 999,
                      opacity: strikeProgress > 0 ? 0.8 : 0,
                    }}
                  />
                </div>
              );
            })}
          </div>
        ))}
      </div>

      {/* --- GRID --- */}
      <div
        style={{
          width: gridContainerWidth,
          height: gridContainerHeight,
          position: "relative",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* Letters Layer */}
        {GRID_ROWS.map((rowStr, rowIndex) => (
          <div
            key={`row-${rowIndex}`}
            style={{
              display: "flex",
              flexDirection: "row",
              width: "100%",
              height: cellHeight,
            }}
          >
            {rowStr.split("").map((char, colIndex) => (
              <div
                key={`cell-${rowIndex}-${colIndex}`}
                style={{
                  width: cellWidth,
                  height: cellHeight,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: 6 * u,
                  fontWeight: 800,
                }}
              >
                {char}
              </div>
            ))}
          </div>
        ))}

        {/* Highlights (SVG Overlay) Layer */}
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            overflow: "visible",
          }}
        >
          {WORDS_TO_FIND.map((item, index) => {
            const wordStartTime = startDelay + index * framesPerWord;
            const loopStart = wordStartTime;
            const loopEnd = wordStartTime + framesPerWord * 0.4;

            const progress = interpolate(
              frame,
              [loopStart, loopEnd],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            if (progress === 0) return null;

            // Calculate geometry
            const startX = item.start[1] * cellWidth + cellWidth / 2;
            const startY = item.start[0] * cellHeight + cellHeight / 2;
            const endX = item.end[1] * cellWidth + cellWidth / 2;
            const endY = item.end[0] * cellHeight + cellHeight / 2;

            const dx = endX - startX;
            const dy = endY - startY;
            const length = Math.sqrt(dx * dx + dy * dy);
            const angle = Math.atan2(dy, dx) * (180 / Math.PI);

            // Pill dimensions
            const pillHeight = cellHeight * 0.85;
            const rx = pillHeight / 2;
            const pillWidth = length + pillHeight;
            const perimeter = 2 * (pillWidth - 2 * rx) + 2 * Math.PI * rx;

            const drawProgress = spring({
              fps,
              frame: frame - loopStart,
              config: { damping: 14, stiffness: 80 },
              durationInFrames: loopEnd - loopStart,
            });

            const strokeDashoffset = interpolate(
               drawProgress,
               [0, 1],
               [perimeter, 0]
            );

            return (
              <g
                key={`highlight-${item.word}`}
                transform={`translate(${startX}, ${startY}) rotate(${angle})`}
              >
                <rect
                  x={-rx}
                  y={-rx}
                  width={pillWidth}
                  height={pillHeight}
                  rx={rx}
                  fill="none"
                  stroke={highlightColor}
                  strokeWidth={0.8 * u}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeDasharray={perimeter}
                  strokeDashoffset={strokeDashoffset}
                  style={{ opacity: 0.9 }}
                />
                {/* Optional: Add a subtle inner offset line to make it look more "drawn" */}
                <rect
                  x={-rx + 1}
                  y={-rx + 1}
                  width={pillWidth - 2}
                  height={pillHeight - 2}
                  rx={rx - 1}
                  fill="none"
                  stroke={highlightColor}
                  strokeWidth={0.2 * u}
                  strokeDasharray={perimeter}
                  strokeDashoffset={strokeDashoffset * 1.05} // Slightly different speed for sketchy feel
                  style={{ opacity: 0.5 }}
                />
              </g>
            );
          })}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default WordSearchAnimation;